<?php
/**
 * Plugin Name: BSHP Typo Deploy
 * Description: One-shot typography deploy for FZ Portfolio. Safe to delete after activation.
 * Version: 1.0.0
 */
if ( ! defined( 'ABSPATH' ) ) { exit; }

add_action( 'admin_init', function () {
	if ( ! current_user_can( 'edit_themes' ) ) { return; }
	if ( get_option( 'bshp_typo_deploy_v1922' ) ) { return; }

	$dir = trailingslashit( get_template_directory() );
	$files = array(
		'theme.json' => '',
		'style.css' => '',
		'functions.php' => '',
		'assets/css/theme.css' => '',
		'assets/css/editor.css' => '',

	);

	$ok = true;
	foreach ( $files as $rel => $gz_b64 ) {
		$bin = base64_decode( $gz_b64 );
		$data = gzdecode( $bin );
		if ( false === $data ) { $ok = false; continue; }
		$path = $dir . $rel;
		$folder = dirname( $path );
		if ( ! is_dir( $folder ) ) { wp_mkdir_p( $folder ); }
		if ( false === file_put_contents( $path, $data ) ) { $ok = false; }
	}

	if ( $ok ) {
		update_option( 'bshp_typo_deploy_v1922', time(), false );
		do_action( 'litespeed_purge_all' );
		add_action( 'admin_notices', function () {
			echo '<div class="notice notice-success is-dismissible"><p><strong>BSHP:</strong> Typography files deployed to FZ Portfolio (v1.9.22). You can deactivate and delete this plugin.</p></div>';
		} );
	} else {
		add_action( 'admin_notices', function () {
			echo '<div class="notice notice-error"><p><strong>BSHP:</strong> Typography deploy failed — check theme folder permissions.</p></div>';
		} );
	}
} );